// Phase 2 tests (Claude build only, site/js/model.js): heater area, installed equipment
// cost, total annualized cost (TAC) optimum, and fixed-area turndown.
// Expected values: tests/handcalc-expected.json -> phase2, generated by the independent
// Python reference (tests/reference/handcalc_reference.py). Run: npm test
import { test, describe } from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync, existsSync } from 'node:fs';
import { fileURLToPath, pathToFileURL } from 'node:url';
import { dirname, join } from 'node:path';

const ROOT = join(dirname(fileURLToPath(import.meta.url)), '..');
const EXP = JSON.parse(readFileSync(join(ROOT, 'tests/handcalc-expected.json'), 'utf8'));
const MODEL = join(ROOT, 'site/js/model.js');
const REL = 0.005;

const near = (actual, expected, key, rel = REL) => {
  assert.ok(typeof actual === 'number' && Number.isFinite(actual), `${key}: got ${actual}`);
  const r = Math.abs(actual - expected) / Math.abs(expected);
  assert.ok(r <= rel, `${key}: got ${actual}, expected ${expected} (off ${(100 * r).toFixed(3)} %)`);
};
const get = (o, path) => path.split('.').reduce((x, k) => (x == null ? undefined : x[k]), o);

describe('Phase 2 (site/js/model.js)', { skip: !existsSync(MODEL) && 'model.js not built' }, () => {
  let M;
  const load = async () => (M ??= await import(pathToFileURL(MODEL)));

  test('exports the Phase 2 functions', async () => {
    await load();
    for (const fn of ['heaterArea', 'compressorCost', 'heaterCost', 'crf', 'tacAt', 'sweepTAC', 'optimumDT', 'turndownAt', 'sweepTurndown']) {
      assert.equal(typeof M[fn], 'function', `missing export ${fn}()`);
    }
  });

  test('DEFAULT_INPUTS include the Phase 2 inputs', async () => {
    await load();
    for (const [k, v] of Object.entries(EXP.phase2Inputs)) near(M.DEFAULT_INPUTS[k], v, `DEFAULT_INPUTS.${k}`);
  });

  test('design point, costs, and TAC optimum match the reference', async () => {
    await load();
    const out = M.simulate({});
    const failures = [];
    for (const [key, exp] of Object.entries(EXP.phase2)) {
      if (!key.startsWith('design.')) continue;
      const v = get(out, key);
      try {
        if (key === 'design.optimum.dT') assert.ok(Math.abs(v - exp) <= 0.1 + 1e-9, `${key}: got ${v}, expected ${exp} ± 0.1 K`);
        else near(v, exp, key);
      } catch (e) { failures.push(e.message); }
    }
    assert.deepEqual(failures, [], `\n  ${failures.join('\n  ')}`);
  });

  test('fixed-area turndown matches the reference', async () => {
    await load();
    for (const f of [0.75, 0.5]) {
      const t = M.turndownAt(M.DEFAULT_INPUTS, f);
      for (const k of ['dT', 'r', 'kWh_per_t', 'cost_per_t']) near(t[k], EXP.phase2[`turndown.${f}.${k}`], `turndown(${f}).${k}`);
    }
  });

  test('limiting cases and "how does that make sense?" trends', async () => {
    await load();
    const base = M.simulate({});
    // full load reproduces the design point
    near(M.turndownAt(M.DEFAULT_INPUTS, 1).kWh_per_t, base.mvr.kWh_per_t, 'turndown(1) = design kWh/t');
    // A is inversely proportional to dT
    const a3 = M.heaterArea({ Q_kW: 1000, U: 2000, dT: 3 }), a6 = M.heaterArea({ Q_kW: 1000, U: 2000, dT: 6 });
    near(a3 / a6, 2, 'A(3K)/A(6K)');
    // CRF limits: zero interest -> 1/n
    near(M.crf(1e-9, 10), 0.1, 'crf(i->0, 10) = 1/n', 1e-6);
    // interior optimum, and it moves the physically expected way
    const opt = base.design.optimum.dT;
    assert.ok(opt > 1 && opt < 15, `optimum ${opt} K not interior`);
    assert.ok(M.simulate({ ce: 2 * M.DEFAULT_INPUTS.ce }).design.optimum.dT <= opt, 'pricier electricity should not raise optimum dT');
    assert.ok(M.simulate({ U: 3000 }).design.optimum.dT <= opt, 'higher U (cheaper area) should not raise optimum dT');
    assert.ok(M.simulate({ U: 1000 }).design.optimum.dT >= opt, 'lower U (dearer area) should not lower optimum dT');
  });

  test('outside the cost tables: null + warning, never NaN', async () => {
    await load();
    const out = M.simulate({ F: 50000, dT_heater: 1 });   // heater area beyond the DOE table
    assert.equal(out.design.TAC, null);
    assert.ok(out.warnings.some((w) => /cost table/i.test(w)), 'expected a cost-table warning');
    assert.ok(!JSON.stringify(out.design).includes('NaN'));
  });
});
